/**
 * Vega-Lite specs checked against Vega-Lite's own JSON schema on write (TEMPRA-214): fast,
 * synchronous and free of Worker APIs, so a malformed chart's lint is in the write result with a
 * path into the spec and words an agent can act on ("mark: "notamark" is not one of "arc",
 * "area", … or an object"), rather than an exception from inside Vega after the write.
 *
 * The schema is the pinned Vega-Lite's (`vega-lite-schema.ts`, generated by
 * `scripts/vega-lite-schema.ts` without its descriptions). It is checked here by a small
 * validator for the keywords that schema uses, not a general one: general validators either
 * compile code (`new Function`, which Workers refuse) or report every failed branch of every
 * `anyOf`, hundreds of lines for one typo. At an `anyOf` this one keeps the branch that got
 * furthest into the value, and when every branch fails on the value itself, says what they would
 * all have taken.
 */
import { VEGA_LITE_SCHEMA_JSON } from "./vega-lite-schema";

type Schema = boolean | SchemaObject;

interface SchemaObject {
  $ref?: string;
  type?: string | string[];
  anyOf?: Schema[];
  properties?: Record<string, Schema>;
  additionalProperties?: Schema;
  items?: Schema;
  required?: string[];
  const?: unknown;
  enum?: unknown[];
  minimum?: number;
  maximum?: number;
  minItems?: number;
  maxItems?: number;
  minProperties?: number;
  minLength?: number;
  maxLength?: number;
}

type Path = (string | number)[];

/** One thing wrong with the spec, at a path into it. */
type Issue =
  /** The value is not one of these (JSON values, or "a number", "an object", …). */
  | { path: Path; kind: "expected"; expected: string[] }
  | { path: Path; kind: "missing"; name: string }
  | { path: Path; kind: "extra"; name: string; allowed: string[] }
  | { path: Path; kind: "other"; message: string };

/** A problem found in a spec: a path into it ("encoding.x.type") and what is wrong there. */
export interface SpecProblem {
  path: string;
  message: string;
}

/** The most problems one chart reports; the first ones found are the ones to fix first. */
const MAX_PROBLEMS = 3;
/** The most values an "is not one of" lists before an ellipsis. */
const MAX_LISTED = 12;

let schema: { root: SchemaObject; definitions: Record<string, Schema> } | null = null;

function loaded() {
  if (!schema) {
    const s = JSON.parse(VEGA_LITE_SCHEMA_JSON) as SchemaObject & {
      definitions: Record<string, Schema>;
    };
    schema = { root: s, definitions: s.definitions };
  }
  return schema;
}

function resolve(ref: string): Schema {
  const name = ref.replace(/^#\/definitions\//, "");
  const defs = loaded().definitions;
  return defs[name] ?? defs[decodeURIComponent(name)] ?? true;
}

const typeName: Record<string, string> = {
  string: "a string",
  number: "a number",
  integer: "a whole number",
  boolean: "true or false",
  object: "an object",
  array: "an array",
  null: "null",
};

function isType(value: unknown, type: string): boolean {
  switch (type) {
    case "string":
      return typeof value === "string";
    case "number":
      return typeof value === "number" && Number.isFinite(value);
    case "integer":
      return Number.isInteger(value);
    case "boolean":
      return typeof value === "boolean";
    case "null":
      return value === null;
    case "array":
      return Array.isArray(value);
    case "object":
      return typeof value === "object" && value !== null && !Array.isArray(value);
    default:
      return true;
  }
}

const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** What is wrong with `value` against `s`, at `path`; nothing when it conforms. */
function check(s: Schema, value: unknown, path: Path): Issue[] {
  if (s === true) return [];
  if (s === false) return [{ path, kind: "other", message: "is not allowed here" }];
  if (s.$ref) return check(resolve(s.$ref), value, path);
  if (s.anyOf) return checkAnyOf(s.anyOf, value, path);
  if (s.const !== undefined && value !== s.const) {
    return [{ path, kind: "expected", expected: [JSON.stringify(s.const)] }];
  }
  if (s.enum && !s.enum.includes(value as never)) {
    return [{ path, kind: "expected", expected: s.enum.map((v) => JSON.stringify(v)) }];
  }
  if (s.type !== undefined) {
    const types = Array.isArray(s.type) ? s.type : [s.type];
    if (!types.some((t) => isType(value, t))) {
      return [{ path, kind: "expected", expected: types.map((t) => typeName[t] ?? t) }];
    }
  }
  const out: Issue[] = [];
  if (typeof value === "number") {
    if (s.minimum !== undefined && value < s.minimum) {
      out.push({ path, kind: "other", message: `is less than ${s.minimum}` });
    }
    if (s.maximum !== undefined && value > s.maximum) {
      out.push({ path, kind: "other", message: `is more than ${s.maximum}` });
    }
  }
  if (typeof value === "string") {
    if (s.minLength !== undefined && value.length < s.minLength) {
      out.push({ path, kind: "other", message: `is shorter than ${s.minLength} characters` });
    }
    if (s.maxLength !== undefined && value.length > s.maxLength) {
      out.push({ path, kind: "other", message: `is longer than ${s.maxLength} characters` });
    }
  }
  if (Array.isArray(value)) {
    if (s.minItems !== undefined && value.length < s.minItems) {
      out.push({ path, kind: "other", message: `has fewer than ${s.minItems} items` });
    }
    if (s.maxItems !== undefined && value.length > s.maxItems) {
      out.push({ path, kind: "other", message: `has more than ${s.maxItems} items` });
    }
    if (s.items !== undefined) {
      for (let i = 0; i < value.length; i++) out.push(...check(s.items, value[i], [...path, i]));
    }
  }
  if (isObject(value)) {
    const keys = Object.keys(value);
    if (s.minProperties !== undefined && keys.length < s.minProperties) {
      out.push({ path, kind: "other", message: `has fewer than ${s.minProperties} properties` });
    }
    for (const name of s.required ?? []) {
      if (!(name in value)) out.push({ path, kind: "missing", name });
    }
    const props = s.properties ?? {};
    for (const key of keys) {
      const sub = props[key];
      if (sub !== undefined) out.push(...check(sub, value[key], [...path, key]));
      else if (s.additionalProperties === false) {
        out.push({ path, kind: "extra", name: key, allowed: Object.keys(props) });
      } else if (s.additionalProperties !== undefined) {
        out.push(...check(s.additionalProperties, value[key], [...path, key]));
      }
    }
  }
  return out;
}

/**
 * An `anyOf`: nothing when a branch takes the value. When every branch fails on the value itself
 * (its type or its value, not something inside it), one issue listing what they would take;
 * otherwise the issues of the branch that got furthest in (its deepest issue deepest, then the
 * fewest issues), so a typo in `encoding.x.type` is reported there and not as eight shapes `x`
 * does not have.
 */
function checkAnyOf(branches: Schema[], value: unknown, path: Path): Issue[] {
  const tried: Issue[][] = [];
  for (const b of branches) {
    const issues = check(b, value, path);
    if (issues.length === 0) return [];
    tried.push(issues);
  }
  const atValue = (issues: Issue[]) =>
    issues.length === 1 && issues[0]?.kind === "expected" && issues[0].path.length === path.length;
  if (tried.every(atValue)) {
    const expected = [
      ...new Set(tried.flatMap((i) => (i[0]?.kind === "expected" ? i[0].expected : []))),
    ];
    return [{ path, kind: "expected", expected }];
  }
  const depth = (issues: Issue[]) => Math.max(...issues.map((i) => i.path.length));
  let best = tried.find((i) => !atValue(i)) ?? [];
  for (const issues of tried) {
    if (atValue(issues)) continue;
    const d = depth(issues) - depth(best);
    if (d > 0 || (d === 0 && issues.length < best.length)) best = issues;
  }
  return best;
}

/** `layer[0].encoding.x`: a path as an agent would write it into the spec. */
function pathText(path: Path): string {
  let out = "";
  for (const p of path) {
    if (typeof p === "number") out += `[${p}]`;
    else if (/^[A-Za-z_$][\w$]*$/.test(p)) out += out ? `.${p}` : p;
    else out += `[${JSON.stringify(p)}]`;
  }
  return out;
}

function shown(value: unknown): string {
  if (isObject(value)) return "an object";
  if (Array.isArray(value)) return "an array";
  const text = JSON.stringify(value) ?? String(value);
  return text.length > 40 ? `${text.slice(0, 39)}…` : text;
}

/**
 * What a value should have been: the values first (a typo of one named), then the kinds, so
 * `"pt" is not one of "arc", "area", "bar", … or an object (did you mean "point"?)`.
 */
function expectedText(value: unknown, expected: string[]): string {
  const values = expected.filter((e) => !Object.values(typeName).includes(e));
  const kinds = expected.filter((e) => Object.values(typeName).includes(e));
  const named = values.length > MAX_LISTED ? [...values.slice(0, MAX_LISTED), "…"] : values;
  const all = [...named, ...kinds];
  const said =
    all.length === 1
      ? (all[0] ?? "")
      : `${values.length > 0 ? "one of " : ""}${all.slice(0, -1).join(", ")} or ${all.at(-1)}`;
  const near =
    typeof value === "string"
      ? closest(
          value,
          values.map((v) => JSON.parse(v)).filter((v): v is string => typeof v === "string"),
        )
      : null;
  return `${said}${near ? ` (did you mean ${JSON.stringify(near)}?)` : ""}`;
}

/** The closest of `names` to `name`, when it is close enough to be a typo of it. */
function closest(name: string, names: string[]): string | null {
  let best: string | null = null;
  let bestD = Math.max(2, Math.floor(name.length / 3)) + 1;
  for (const n of names) {
    const d = distance(name.toLowerCase(), n.toLowerCase());
    if (d < bestD) {
      best = n;
      bestD = d;
    }
  }
  return best;
}

function distance(a: string, b: string): number {
  const row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let prev = row[0] ?? 0;
    row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const was = row[j] ?? 0;
      row[j] = Math.min(was + 1, (row[j - 1] ?? 0) + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = was;
    }
  }
  return row[b.length] ?? 0;
}

function valueAt(spec: unknown, path: Path): unknown {
  let v = spec;
  for (const p of path) v = (v as Record<string | number, unknown> | undefined)?.[p];
  return v;
}

function problemOf(spec: unknown, issue: Issue): SpecProblem {
  const at = pathText(issue.path);
  switch (issue.kind) {
    case "expected":
      return {
        path: at,
        message: `${shown(valueAt(spec, issue.path))} is not ${expectedText(valueAt(spec, issue.path), issue.expected)}`,
      };
    case "missing":
      return { path: at, message: `has no ${JSON.stringify(issue.name)}, which it needs` };
    case "extra": {
      const near = closest(issue.name, issue.allowed);
      return {
        path: at,
        message: `${JSON.stringify(issue.name)} is not a property here${near ? ` (did you mean ${JSON.stringify(near)}?)` : ""}`,
      };
    }
    default:
      return { path: at, message: issue.message };
  }
}

/**
 * What Vega-Lite's schema says is wrong with a spec, at most MAX_PROBLEMS, in the order found;
 * nothing for a spec it takes. `path` is "" for the spec as a whole.
 */
export function checkChartSpec(spec: unknown): SpecProblem[] {
  const issues = check(loaded().root, spec, []);
  const seen = new Set<string>();
  const out: SpecProblem[] = [];
  for (const issue of issues) {
    const p = problemOf(spec, issue);
    const key = `${p.path}\n${p.message}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(p);
    if (out.length === MAX_PROBLEMS) break;
  }
  return out;
}
